/**
 * Crash-stage contracts for the durable LMDB store identity used by Frontier OmniSketch.
 *
 * <p>
 * Reflection keeps these tests compilable while the deliberately small persistence seam is introduced test-first. The
 * required production API is a package-private {@code StorePropertiesFileOps} interface and a
 * {@code StoreProperties(File, StorePropertiesFileOps)} constructor. The interface methods are pinned by
 * {@link #newHarness(Path)}.
 * </p>
 */
class StorePropertiesAtomicSaveContractTest {

	private static final String FILE_OPS_TYPE = "org.eclipse.rdf4j.sail.lmdb.StorePropertiesFileOps";

	@Test
	void saveForcesTemporaryBeforeAtomicReplaceAndDirectoryForce(@TempDir Path directory) throws Exception {
		AtomicSaveHarness harness = newHarness(directory);
		harness.properties.setVersion("before-frontier");

		harness.properties.save();

		Path target = directory.resolve(StoreProperties.FILE_NAME).toAbsolutePath().normalize();
		Path temporary = directory.resolve(StoreProperties.FILE_NAME + ".tmp").toAbsolutePath().normalize();
		assertStrictlyOrdered(harness.operations, "createDirectories", "writeAndForce", "moveAtomically",
				"forceDirectory");
		assertEquals(directory.toAbsolutePath().normalize(), harness.only("createDirectories").firstPath());
		assertEquals(temporary, harness.only("writeAndForce").firstPath());
		assertEquals(temporary, harness.only("moveAtomically").firstPath());
		assertEquals(target, harness.only("moveAtomically").secondPath());
		assertEquals(directory.toAbsolutePath().normalize(), harness.only("forceDirectory").firstPath());

		StoreProperties loaded = new StoreProperties(directory.toFile());
		assertTrue(loaded.load());
		assertEquals("before-frontier", loaded.getVersion());
	}

	@Test
	void failureBeforeAtomicReplacePreservesPriorPropertiesByteForByte(@TempDir Path directory) throws Exception {
		AtomicSaveHarness harness = newHarness(directory);
		Path target = directory.resolve(StoreProperties.FILE_NAME).toAbsolutePath().normalize();

		harness.properties.setVersion("published");
		harness.properties.save();
		byte[] publishedBytes = Files.readAllBytes(target);

		harness.operations.clear();
		harness.failAtomicReplace = true;
		harness.properties.setVersion("must-not-leak");
		assertThrows(IllegalStateException.class, harness.properties::save);

		assertArrayEquals(publishedBytes, Files.readAllBytes(target),
				"a failed pre-publication save must leave the last durable properties file byte-for-byte intact");
		assertEquals(1, harness.count("moveAtomically"));
		assertEquals(0, harness.count("forceDirectory"),
				"the directory is forced only after a successful atomic publication");

		harness.operations.clear();
		harness.failAtomicReplace = false;
		harness.properties.save();
		StoreProperties retried = new StoreProperties(directory.toFile());
		assertTrue(retried.load());
		assertEquals("must-not-leak", retried.getVersion(),
				"a failed publication must retain dirty state so a later save can retry");
	}

	@Test
	void frontierFactoryObserverSeesStoreIdentityOnlyAfterDurableSaveReturns(@TempDir Path directory)
			throws Exception {
		AtomicSaveHarness harness = newHarness(directory);
		Path target = directory.resolve(StoreProperties.FILE_NAME).toAbsolutePath().normalize();

		UUID created = harness.properties.getOrCreateStoreId();
		assertFalse(Files.exists(target), "identity creation alone must not pretend that the UUID is durable");

		harness.properties.save();

		assertEquals("forceDirectory", harness.operations.get(harness.operations.size() - 1).name,
				"the save call must not return to the Frontier service factory before the directory is forced");
		StoreProperties observedByFrontierFactory = new StoreProperties(directory.toFile());
		assertTrue(observedByFrontierFactory.load());
		assertEquals(created, observedByFrontierFactory.getOrCreateStoreId());
	}

	private static AtomicSaveHarness newHarness(Path directory) throws Exception {
		ClassLoader loader = StorePropertiesAtomicSaveContractTest.class.getClassLoader();
		Class<?> fileOpsType = assertDoesNotThrow(() -> Class.forName(FILE_OPS_TYPE, true, loader),
				"StoreProperties needs an injectable file-operations seam for deterministic crash-stage tests");
		assertTrue(fileOpsType.isInterface(), FILE_OPS_TYPE + " must be an interface");

		Method createDirectories = fileOpsType.getDeclaredMethod("createDirectories", Path.class);
		Method writeAndForce = fileOpsType.getDeclaredMethod("writeAndForce", Path.class, byte[].class);
		Method moveAtomically = fileOpsType.getDeclaredMethod("moveAtomically", Path.class, Path.class);
		Method forceDirectory = fileOpsType.getDeclaredMethod("forceDirectory", Path.class);
		Method deleteIfExists = fileOpsType.getDeclaredMethod("deleteIfExists", Path.class);
		assertNotNull(createDirectories);
		assertNotNull(writeAndForce);
		assertNotNull(moveAtomically);
		assertNotNull(forceDirectory);
		assertNotNull(deleteIfExists);

		AtomicSaveHarness harness = new AtomicSaveHarness();
		Object fileOps = Proxy.newProxyInstance(loader, new Class<?>[] { fileOpsType },
				(proxy, method, arguments) -> harness.invoke(proxy, method, arguments));
		Constructor<StoreProperties> constructor = StoreProperties.class.getDeclaredConstructor(File.class,
				fileOpsType);
		constructor.setAccessible(true);
		harness.properties = constructor.newInstance(directory.toFile(), fileOps);
		return harness;
	}

	private static void assertStrictlyOrdered(List<Operation> operations, String... names) {
		int previous = -1;
		for (String name : names) {
			int next = -1;
			for (int i = previous + 1; i < operations.size(); i++) {
				if (name.equals(operations.get(i).name)) {
					next = i;
					break;
				}
			}
			assertTrue(next > previous,
					name + " was not observed after operation index " + previous + ": " + operations);
			previous = next;
		}
	}

	private static final class AtomicSaveHarness {

		private final List<Operation> operations = new ArrayList<>();
		private StoreProperties properties;
		private boolean failAtomicReplace;

		private Object invoke(Object proxy, Method method, Object[] arguments) throws IOException {
			if (method.getDeclaringClass() == Object.class) {
				return switch (method.getName()) {
				case "equals" -> proxy == arguments[0];
				case "hashCode" -> System.identityHashCode(proxy);
				case "toString" -> "AtomicStorePropertiesFileOps";
				default -> throw new AssertionError("Unexpected Object method: " + method);
				};
			}
			return switch (method.getName()) {
			case "createDirectories" -> {
				Path directory = normalized(arguments[0]);
				operations.add(new Operation(method.getName(), directory, null));
				yield Files.createDirectories(directory);
			}
			case "writeAndForce" -> {
				Path path = normalized(arguments[0]);
				operations.add(new Operation(method.getName(), path, null));
				Files.write(path, ((byte[]) arguments[1]).clone());
				yield null;
			}
			case "moveAtomically" -> {
				Path source = normalized(arguments[0]);
				Path target = normalized(arguments[1]);
				operations.add(new Operation(method.getName(), source, target));
				if (failAtomicReplace) {
					throw new IOException("simulated failure before atomic replacement");
				}
				Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
				yield null;
			}
			case "forceDirectory" -> {
				Path directory = normalized(arguments[0]);
				operations.add(new Operation(method.getName(), directory, null));
				yield null;
			}
			case "deleteIfExists" -> {
				Path path = normalized(arguments[0]);
				operations.add(new Operation(method.getName(), path, null));
				yield Files.deleteIfExists(path);
			}
			default -> throw new AssertionError("Unexpected StoreProperties file operation: " + method);
			};
		}

		private Operation only(String name) {
			List<Operation> matching = operations.stream().filter(operation -> name.equals(operation.name)).toList();
			assertEquals(1, matching.size(), () -> "Expected one " + name + " operation but observed " + operations);
			return matching.get(0);
		}

		private long count(String name) {
			return operations.stream().filter(operation -> name.equals(operation.name)).count();
		}

		private static Path normalized(Object path) {
			return ((Path) path).toAbsolutePath().normalize();
		}
	}

	private record Operation(String name, Path firstPath, Path secondPath) {
	}
}
